test('1086 administrator pages are allowed while family users cannot open them',()=>{role='admin';for(const k of ['capacity1086','parent1086','import1086','roles1086'])assert.ok(allowedPages().includes(k));for(const r of ['parent','student']){role=r;assert.ok(!allowedPages().includes('roles1086'));assert.ok(!allowedPages().includes('parent1086'))}});
test('capacity percentages and remaining seats match displayed counts',()=>{for(const c of v1086Classes){assert.ok(c.enrolled<=c.capacity);assert.ok(c.capacity-c.enrolled>=0)}const html=v1086Capacity();assert.ok(html.includes('60%'));assert.ok(html.includes('85%'));assert.ok(html.includes('100%'));assert.ok(html.includes('المقاعد المتاحة: 0'))});
test('student preview includes only own record; parent preview has two linked children',()=>{role='student';const student=v1086Family();assert.ok(student.includes('STU00125'));assert.ok(!student.includes('STU00126'));role='parent';const parent=v1086Family();assert.ok(parent.includes('STU00125'));assert.ok(parent.includes('STU00126'))});
test('import confirmation stays disabled with sample issues',()=>{const html=v1086Import();assert.ok(html.includes('disabled>تأكيد الاستيراد'));assert.ok(html.includes('لا يتم تحليل أو رفع ملفات Excel'));assert.ok(html.includes('120'));assert.equal(98+12+10,120)});
test('role filters display only matching sample issues',()=>{v1086RoleFilter='conflict';const html=v1086Roles();assert.ok(html.includes('أحمد علي محمد'));assert.ok(!html.includes('فاطمة حسن'));v1086RoleFilter='all'});
